"use client";

import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { assetFilters } from "@/data/mockData";
import {
    Flame,
    Sparkles,
    TrendingUp,
    Layers,
    Video,
    Palette,
    Search
} from "lucide-react";

const filterIcons: Record<string, any> = {
    "Recommended": Sparkles,
    "New Assets": Flame,
    "Most Popular": TrendingUp,
    "UI Kits": Layers,
    "Overlays": Video,
    "LUTs": Palette,
    "Pinterest Tools": Search,
};

const Sidebar = () => {
    const searchParams = useSearchParams();
    const currentFilter = searchParams.get("filter") || "recommended";

    return (
        <aside className="w-72 hidden lg:block sticky top-32 h-[calc(100vh-8rem)] overflow-y-auto no-scrollbar pr-8 border-r border-border/50">
            <div className="flex flex-col space-y-2">
                <p className="text-[10px] font-black tracking-[0.3em] uppercase text-secondary mb-6 pl-4">
                    Categories
                </p>
                {assetFilters.map((item) => {
                    const slug = item.toLowerCase().replace(' ', '-');
                    const isActive = currentFilter === slug;
                    const Icon = filterIcons[item] || Sparkles;

                    return (
                        <Link
                            key={item}
                            href={`/assets?filter=${slug}`}
                            className={`group flex items-center justify-between px-6 py-4 transition-all duration-300 relative border-2 mb-2 ${isActive
                                ? "bg-foreground text-background border-foreground"
                                : "bg-background text-foreground border-transparent hover:border-foreground/10 hover:translate-x-1"
                                }`}
                        >
                            <div className="flex items-center gap-4">
                                <Icon size={16} strokeWidth={isActive ? 3 : 2} className={isActive ? "text-background" : "text-foreground"} />
                                <span className="text-[11px] font-black uppercase tracking-[0.2em]">{item}</span>
                            </div>

                            {isActive && (
                                <div className="w-1.5 h-1.5 bg-background rounded-full" />
                            )}
                        </Link>
                    );
                })}
            </div>

            <div className="mt-12 p-6 bg-zinc-100 dark:bg-zinc-900 border-2 border-foreground shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] dark:shadow-[4px_4px_0px_0px_rgba(255,255,255,1)]">
                <p className="text-[10px] font-black uppercase tracking-widest mb-2">Pro Access</p>
                <p className="text-[11px] font-medium text-secondary mb-4 leading-relaxed">Unlock unlimited downloads and premium source files.</p>
                <Link
                    href="/premium"
                    className="block text-center text-[10px] font-black uppercase tracking-widest bg-foreground text-background py-3 hover:opacity-90 transition-opacity"
                >
                    Upgrade Now
                </Link>
            </div>
        </aside>
    );
};

export default Sidebar;
